describe('Add and Remove Product from Cart', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should add a product to cart and update cart badge', () => {
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
    cy.url().should('include', '/cart.item');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping_cart_badge"]').should('be.visible');
    cy.get('[data-testid="shopping_cart_badge"]').should('contain', '1');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('contain', 'Remove');
    cy.get('[data-testid="remove-sauce-labs-backpack"]').should('be.visible');
  });

  it('should remove a product from cart and update cart badge', () => {
    cy.get('[data-testid="user-name"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping_cart_badge"]').should('contain', '1');
    cy.get('[data-testid="remove-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping_cart_badge"]').should('not.exist');
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').should('contain', 'Add to cart');
    cy.get('[data-testid="remove-sauce-labs-backpack"]').should('not.exist');
  });
});
